        // The §5 zero form: all-zero storage; specified defaults live only in construction.
        public static void ZeroTestData(TestData value)
        {
            value.A = 0;
            value.B = 0;
            value.C = 0;
            value.D = 0;
            value.E = 0;
            value.F = 0;
            value.G = false;
