            value.FloatValue = 0.0f;
            value.CompressedFloatValue = 0.0f;
            value.DoubleValue = 0.0;
            value.Int8Value = 0;
            value.Int16Value = 0;
            value.Uint8Value = 0;
            value.Uint16Value = 0;
            value.Uint32Value = 0;
            value.Uint64Value = 0;
