            if (!batch.SerializeDouble(ref value.DoubleValue))
            {
                return false;
            }
            {
                uint rawValue = (byte)value.Int8Value;
                if (!batch.SerializeBits(ref rawValue, 8))
                {
                    return false;
                }
            }
            {
