                {
                    return false;
                }
            }
            {
                uint rawValue = value.Uint8Value;
                if (!batch.SerializeBits(ref rawValue, 8))
                {
                    return false;
                }
            }
            {
                uint rawValue = value.Uint16Value;
                if (!batch.SerializeBits(ref rawValue, 16))
                {
                    return false;
                }
