            if (!batch.SerializeBits(ref value.Uint32Value, 32))
            {
                return false;
            }
            if (!batch.SerializeBits64(ref value.Uint64Value, 64))
            {
                return false;
            }
            {
                ulong rawValue = (ulong)value.Int64Full;
